240: static inline void MC_avg_mmx (const int width, int height, uint8_t * dest,
241: 			       const uint8_t * ref, const int stride)
242: {
243:     mmx_zero_reg ();
244: 
245:     do {
246: 	mmx_average_2_U8 (dest, dest, ref);
247: 
248: 	if (width == 16)
249: 	    mmx_average_2_U8 (dest+8, dest+8, ref+8);
250: 
251: 	dest += stride;
252: 	ref += stride;
253:     } while (--height);
254: }
