714: 	movq_r2r (mm0, mm6);
715: 	pxor_r2r (mm2, mm6);
716: 	pand_r2r (mm6, mm7);
717: 	pand_m2r (mask_one, mm7);
718: 	pavg_r2r (mm2, mm0);
