175: static void * create_shm (x11_instance_t * instance, int size)
176: {
177:     instance->shminfo.shmid = shmget (IPC_PRIVATE, size, IPC_CREAT | 0777);
178:     if (instance->shminfo.shmid == -1)
179: 	goto error;
180: 
181:     instance->shminfo.shmaddr = (char *) shmat (instance->shminfo.shmid, 0, 0);
182:     if (instance->shminfo.shmaddr == (char *)-1)
183: 	goto error;
184: 
185:     /* on linux the IPC_RMID only kicks off once everyone detaches the shm */
186:     /* doing this early avoids shm leaks when we are interrupted. */
187:     /* this would break the solaris port though :-/ */
188:     /* shmctl (instance->shminfo.shmid, IPC_RMID, 0); */
189: 
190:     /* XShmAttach fails on remote displays, so we have to catch this event */
191: 
192:     XSync (instance->display, False);
193:     XSetErrorHandler (handle_error);
194: 
195:     instance->shminfo.readOnly = True;
196:     if (! (XShmAttach (instance->display, &(instance->shminfo))))
197: 	shmerror = 1;
198: 
199:     XSync (instance->display, False);
200:     XSetErrorHandler (NULL);
201:     if (shmerror) {
202:     error:
203: 	fprintf (stderr, "cannot create shared memory\n");
204: 	if (instance->shminfo.shmid != -1) {
205: 	    shmdt (instance->shminfo.shmaddr);
206: 	    shmctl (instance->shminfo.shmid, IPC_RMID, 0);
207: 	}
208: 	return NULL;
209:     }
210: 
211:     return instance->shminfo.shmaddr;
212: }
