410: static int xv_check_extension (x11_instance_t * instance,
411: 			       int fourcc, const char * fourcc_str)
412: {
413:     unsigned int i;
414:     unsigned long j;
415: 
416:     if (!instance->adaptorInfo) {
417: 	unsigned int version;
418: 	unsigned int release;
419: 	unsigned int dummy;
420: 
421: 	if ((XvQueryExtension (instance->display, &version, &release,
422: 			       &dummy, &dummy, &dummy) != Success) ||
423: 	    (version < 2) || ((version == 2) && (release < 2))) {
424: 	    fprintf (stderr, "No xv extension\n");
425: 	    return 1;
426: 	}
427: 
428: 	XvQueryAdaptors (instance->display, instance->window,
429: 			 &instance->adaptors, &instance->adaptorInfo);
430:     }
431: 
432:     for (i = 0; i < instance->adaptors; i++)
433: 	if (instance->adaptorInfo[i].type & XvImageMask)
434: 	    for (j = 0; j < instance->adaptorInfo[i].num_ports; j++)
435: 		if ((! (xv_check_fourcc (instance,
436: 					 instance->adaptorInfo[i].base_id + j,
437: 					 fourcc, fourcc_str))) &&
438: 		    (XvGrabPort (instance->display,
439: 				 instance->adaptorInfo[i].base_id + j,
440: 				 0) == Success)) {
441: 		    instance->port = instance->adaptorInfo[i].base_id + j;
442: 		    return 0;
443: 		}
444: 
445:     fprintf (stderr, "Cannot find xv %s port\n", fourcc_str);
446:     return 1;
